<article class="admin-card"><h2><?= t('المستحقات حسب الطلب','Outstanding balances by order') ?></h2><?php $dues=Db::all("SELECT o.code,o.status,o.subtotal,o.shipping,o.total,COALESCE(SUM(CASE WHEN s.type='seller' THEN s.amount ELSE 0 END),0) AS seller_paid,COALESCE(SUM(CASE WHEN s.type='shipping' THEN s.amount ELSE 0 END),0) AS shipping_paid,COALESCE(SUM(CASE WHEN s.type='refund' THEN s.amount ELSE 0 END),0) AS refund_paid FROM orders o LEFT JOIN settlements s ON s.order_id=o.id WHERE o.status IN ('delivered','refund_pending','refunded') GROUP BY o.id,o.code,o.status,o.subtotal,o.shipping,o.total ORDER BY o.id DESC LIMIT 100"); ?><div class="table-wrap"><table><thead><tr><th><?= t('الطلب','Order') ?></th><th><?= t('متبقي للبائع','Seller remaining') ?></th><th><?= t('متبقي للنقل','Transport remaining') ?></th><th><?= t('متبقي لرد المبلغ','Refund remaining') ?></th></tr></thead><tbody><?php foreach($dues as $d): ?><tr><td><?= e($d['code']) ?><?= badge($d['status']) ?></td><td><?= $d['status']==='delivered'?money((int)$d['subtotal']-(int)$d['seller_paid']):'—' ?></td><td><?= $d['status']==='delivered'?money((int)$d['shipping']-(int)$d['shipping_paid']):'—' ?></td><td><?= $d['status']!=='delivered'?money((int)$d['total']-(int)$d['refund_paid']):'—' ?></td></tr><?php endforeach;if(!$dues){table_empty(4);} ?></tbody></table></div></article>
