<?php $rows=Db::all('SELECT j.*,u.name FROM journals j JOIN users u ON u.id=j.created_by ORDER BY j.id DESC'.$limit); ?><article class="admin-card"><h2><?= t('دفتر القيود','Journal register') ?></h2><div class="table-wrap"><table><thead><tr><th><?= t('القيد','Entry') ?></th><th><?= t('الوصف','Description') ?></th><th><?= t('مدين / دائن','Debit / credit') ?></th><th><?= t('مسجل بواسطة','Recorded by') ?></th></tr></thead><tbody><?php foreach(array_slice($rows,0,25) as $j): ?><tr><td>#<?= $j['id'] ?><small><?= e($j['source']) ?> / <?= e($j['event']) ?></small></td><td><?= e($j['description']) ?></td><td><?php foreach(Db::all('SELECT l.*,a.name_ar,a.name_en FROM journal_lines l JOIN accounts a ON a.id=l.account_id WHERE journal_id=?',[$j['id']]) as $l): ?><small><?= e(localized($l)) ?>: <?= (int)$l['debit']?t('مدين ','DR ').money((int)$l['debit']):t('دائن ','CR ').money((int)$l['credit']) ?></small><?php endforeach; ?></td><td><?= e($j['name']) ?><small><?= e($j['created_at']) ?> UTC</small></td></tr><?php endforeach;if(!$rows){table_empty(4);} ?></tbody></table></div><?php admin_pager($rows,$section,$pn); ?></article>
