<?php elseif($section==='tasks'): ?>
<article class="admin-card"><h2><?= t('مهمة جديدة','New task') ?></h2><?php admin_form('task','tasks','form-grid');field(t('المهمة','Task'),'title','text','','required maxlength="190"');$staffOpts=options_from(Db::all("SELECT id,name FROM users WHERE active=1 AND role<>'member'".($operator['role']==='support'?' AND id='.(int)$operator['id']:'')));select_field(t('المسؤول','Assignee'),'assignee_id',$staffOpts);select_field(t('المشروع — اختياري','Project — optional'),'project_id',[''=>t('بدون مشروع','No project')]+($operator['role']!=='support'?options_from(Db::all('SELECT id,name FROM projects ORDER BY id DESC LIMIT 200')):[]));field(t('الموعد — اختياري','Due date — optional'),'due_date','date');select_field(t('الأولوية','Priority'),'priority',['normal'=>t('عادية','Normal'),'high'=>t('عالية','High')]); ?><button class="button button-green"><?= t('إضافة مهمة','Add task') ?></button></form></article>
<?php $rows=Db::all('SELECT t.*,u.name AS assignee,p.name AS project FROM tasks t LEFT JOIN users u ON u.id=t.assignee_id LEFT JOIN projects p ON p.id=t.project_id'.($operator['role']==='support'?' WHERE t.assignee_id='.(int)$operator['id']:'').' ORDER BY t.id DESC'.$limit); ?><div class="task-board"><?php foreach(['todo','doing','done'] as $column): ?><div class="task-column"><h2><?= e(state_label($column)) ?></h2><?php foreach(array_slice($rows,0,25) as $r):if($r['status']!==$column){continue;} ?><article class="task-card"><b><?= e($r['title']) ?></b><p><?= e($r['assignee']??'') ?> · <?= e($r['due_date']??'') ?></p><small><?= e($r['project']??'') ?><?= $r['priority']==='high'?' / '.t('عالية','High'):'' ?></small><?php admin_form('task-status','tasks','inline-form');hidden_id('task_id',(int)$r['id']);select_field(t('الحالة','Status'),'status',['todo'=>state_label('todo'),'doing'=>state_label('doing'),'done'=>state_label('done')],$r['status']); ?><button class="button button-outline button-small"><?= t('تحديث','Update') ?></button></form></article><?php endforeach; ?></div><?php endforeach; ?></div><?php admin_pager($rows,$section,$pn); ?>
<?php elseif($section==='people'): ?>
<article class="admin-card"><h2><?= t('سجل عمل الفريق','Record team work time') ?></h2><?php admin_form('attendance','people','form-grid');select_field(t('عضو الفريق','Team member'),'user_id',options_from(Db::all("SELECT id,name FROM users WHERE role<>'member' AND active=1")));field(t('تاريخ العمل','Work date'),'work_date','date',date('Y-m-d'),'required');field(t('مدة العمل بالدقائق','Work time in minutes'),'minutes','number','','required min="0" max="1440"');field(t('ملاحظات','Notes'),'notes','text','','maxlength="500"'); ?><button class="button button-green"><?= t('حفظ السجل','Record time') ?></button></form></article>
<?php $rows=Db::all('SELECT a.*,u.name FROM attendance a JOIN users u ON u.id=a.user_id ORDER BY a.work_date DESC,a.id DESC'.$limit); ?><article class="admin-card"><div class="table-wrap"><table><thead><tr><th><?= t('العضو','Team member') ?></th><th><?= t('اليوم','Date') ?></th><th><?= t('المدة','Time') ?></th><th><?= t('ملاحظات','Notes') ?></th></tr></thead><tbody><?php foreach(array_slice($rows,0,25) as $r): ?><tr><td><?= e($r['name']) ?></td><td><?= e($r['work_date']) ?></td><td><?= number_format((int)$r['minutes']/60,2) ?> <?= t('ساعة','hours') ?></td><td><?= e($r['notes']) ?></td></tr><?php endforeach;if(!$rows){table_empty(4);} ?></tbody></table></div><?php admin_pager($rows,$section,$pn); ?></article>
<?php elseif($section==='support'): ?>
<?php $rows=Db::all('SELECT t.*,u.name AS user_name,o.code FROM tickets t LEFT JOIN users u ON u.id=t.user_id LEFT JOIN orders o ON o.id=t.order_id ORDER BY t.id DESC'.$limit); ?><div class="support-grid"><?php foreach(array_slice($rows,0,25) as $r): ?><article class="admin-card"><div class="card-heading"><h2>#<?= $r['id'] ?> — <?= e($r['subject']) ?></h2><?= badge($r['status']) ?></div><p class="caption"><?= e($r['user_name']??'') ?> / <span dir="ltr"><?= e($r['contact_phone']) ?></span> <?= e($r['code']??'') ?></p><p><?= nl2br(e($r['message'])) ?></p><?php admin_form('ticket-response','support');select_field(t('الحالة','Status'),'status',['open'=>state_label('open'),'in_progress'=>state_label('in_progress'),'closed'=>state_label('closed')],$r['status']); ?><label class="field"><span><?= t('الرد الظاهر في حساب المستخدم','Reply visible in the user account') ?></span><textarea rows="3" name="response" required maxlength="3000"><?= e($r['response']) ?></textarea></label><p class="caption"><?= $r['user_id']?t('الرد يظهر في حساب المستخدم.','The reply appears in the user’s account.'):t('الطلب بدون حساب. تواصل مع صاحب الرقم خارج المنصة وسجل ملخص التواصل.','Guest request. Contact the phone holder outside the platform and record a summary.') ?></p><button class="button button-green button-small"><?= t('حفظ الرد','Save reply') ?></button></form></article><?php endforeach; ?></div><?php if(!$rows): ?><article class="admin-card table-empty"><?= t('لا توجد رسائل دعم.','No support messages.') ?></article><?php endif;admin_pager($rows,$section,$pn); ?>
<?php else: require HASAD_ROOT.'/views/admin-settings-reports.php';endif; ?>
